import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int q = nextInt();
        long[] history = new long[q]; // states before each live change
        int top = 0, printed = 0;
        long value = 0;
        StringBuilder lines = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = next();
            if (cmd.equals("ADD") || cmd.equals("MUL")) {
                long x = nextLong();
                history[top++] = value;
                value = cmd.equals("ADD") ? value + x : value * x;
            } else if (cmd.equals("UNDO")) {
                value = history[--top];
            } else {
                lines.append(value).append('\n');
                printed++;
            }
        }
        System.out.print(printed + "\n" + lines);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	history := []int64{} // states before each live change
	out := []int64{}
	var value int64
	for i := 0; i < q; i++ {
		cmd := string(next())
		switch cmd {
		case "ADD", "MUL":
			x := nextInt()
			history = append(history, value)
			if cmd == "ADD" {
				value += x
			} else {
				value *= x
			}
		case "UNDO":
			value = history[len(history)-1]
			history = history[:len(history)-1]
		default:
			out = append(out, value)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(out)) + "\n")
	for _, v := range out {
		w.WriteString(strconv.FormatInt(v, 10) + "\n")
	}
}
